# (c) Aggregation pipeline: jumlah merchant & rata-rata rating per kategori
pipeline = [
    {
        "$group": {
            "_id": "$kategori",
            "jumlah_merchant": {"$sum": 1},
            "rata_rating": {"$avg": "$rating"}
        }
    },
    {
        "$sort": {"rata_rating": -1}
    }
]
hasil_c = list(db["merchant"].aggregate(pipeline))
print("\n--- (c) Agregasi Merchant per Kategori ---")


--- (c) Agregasi Merchant per Kategori ---

for row in hasil_c:
    print(f"Kategori: {row['_id']:&lt;15} | Jumlah: {row['jumlah_merchant']:&lt;3} | Rata-rata Rating: {row['rata_rating']:.2f}")

